<style>
:root{--ink:#153e49;--paper:#f8f2df;--orange:#be442b;--blue:#24697b;--muted:#546b6b;--line:#c9cebd;--yellow:#e9bc50}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:"Gill Sans","Trebuchet MS",sans-serif}a{color:inherit;text-underline-offset:4px}button,input,select{font:inherit}button{cursor:pointer;min-height:44px;border:1px solid var(--ink);padding:10px 16px;background:transparent;color:var(--ink);border-radius:3px}button:hover{background:#e3e6d3}button:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid var(--orange);outline-offset:3px}.primary{background:var(--ink);color:var(--paper)}.primary:hover{background:var(--blue)}header,main,footer{max-width:1240px;margin:auto;padding:0 28px}.nav{padding:24px 0 18px;border-bottom:1px solid var(--ink);display:flex;justify-content:space-between;gap:12px;font-size:12px;letter-spacing:.12em;text-transform:uppercase}.hero{display:grid;grid-template-columns:1.4fr 1fr;gap:40px;align-items:end;padding:36px 0 28px}h1{font:normal clamp(56px,8vw,112px)/.88 "Palatino Linotype","Book Antiqua",Palatino,serif;margin:0;letter-spacing:-.065em}h1 em{font-weight:normal;color:var(--orange)}.lede{line-height:1.6;max-width:390px;margin:0 0 4px;font-size:18px}.kicker{font-size:11px;letter-spacing:.18em;text-transform:uppercase;margin:0 0 16px}.layout{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(280px,1fr);gap:28px}.port{position:relative;overflow:hidden;aspect-ratio:1.6;background:#d7dfd0;border:1px solid var(--ink)}.port img{width:100%;height:100%;object-fit:cover;display:block}.water{position:absolute;bottom:0;left:0;right:0;height:40%;background:#12566cac;border-top:3px solid #d7eddf;transition:height .45s}.water::before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(0deg,transparent 0 26px,#f7f2d828 27px 28px)}.tide-label{position:absolute;bottom:16px;left:16px;background:var(--paper);padding:12px 16px;border:1px solid var(--ink);max-width:calc(100% - 32px)}.tide-label strong{display:block;font:normal 32px Palatino,serif}.port-caption{position:absolute;top:12px;left:12px;background:var(--paper);padding:7px 10px;font-size:10px;letter-spacing:.12em}.scrub{padding:20px 0;border-bottom:1px solid var(--line)}.scrub label{display:flex;justify-content:space-between;gap:12px}input[type=range]{width:100%;accent-color:var(--orange);margin:18px 0 4px;min-height:28px}.small{font-size:13px;line-height:1.55;color:var(--muted)}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;padding:22px 0}.stat{border-top:2px solid var(--ink);padding-top:10px}.stat span{font-size:11px;text-transform:uppercase;letter-spacing:.08em}.stat strong{display:block;font:normal clamp(21px,3vw,34px) Palatino,serif;margin:6px 0}.stat small{font-size:12px;color:var(--muted)}.danger{color:var(--orange)}h2{font:normal 30px Palatino,serif;margin:0 0 14px}.panel{border-top:4px solid var(--ink);padding-top:18px}.controls{display:grid;grid-template-columns:1fr 1fr;gap:14px}label.field{display:block;font-size:12px;letter-spacing:.04em}input:not([type=range]),select{width:100%;min-width:0;min-height:44px;border:1px solid #91a29b;border-radius:2px;background:#fffcf1;color:var(--ink);padding:9px;margin-top:6px}select{padding-right:4px}.preset{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.preset button{font-size:12px;padding:8px 10px}.events{display:flex;flex-direction:column;gap:13px}.event{padding-bottom:13px;border-bottom:1px solid var(--line)}.rowtop{display:grid;grid-template-columns:1fr 105px 44px;gap:8px;align-items:end}.rowbottom{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:8px}.delete{padding:0;font-size:22px;margin-bottom:0}.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:16px}.actions button{font-size:13px}.chart-wrap{border:1px solid var(--ink);padding:12px;background:#fffcf1}svg{display:block;width:100%;height:auto;overflow:visible}.legend{display:flex;justify-content:space-between;font-size:11px;color:var(--muted);padding:4px}.note{padding:17px 18px;background:#e4e7d6;line-height:1.6;font-size:14px;margin:18px 0}.note strong{font-weight:600}.ledger{margin:30px 0}.ledger-head{display:flex;align-items:baseline;justify-content:space-between;gap:10px}.ledger-list{max-height:280px;overflow:auto;border-top:1px solid var(--ink)}.ledger-line{display:grid;grid-template-columns:92px 1fr 100px 100px;gap:12px;padding:12px 2px;border-bottom:1px solid var(--line);font-size:14px}.ledger-line span:nth-last-child(-n+2){text-align:right;font-variant-numeric:tabular-nums}footer{padding-top:28px;padding-bottom:40px;border-top:1px solid var(--ink);font-size:13px;line-height:1.7}.toast{min-height:22px;font-size:13px;color:var(--orange)}.chart-title{display:flex;justify-content:space-between;align-items:baseline;gap:10px}.chart-title h2{font-size:24px}.zero-key{color:var(--orange);font-size:12px}.tip{font-size:12px;color:var(--muted);line-height:1.5}
