@media(max-width:560px){header,main,footer{padding-left:18px;padding-right:18px}.nav{font-size:10px;letter-spacing:.06em}.hero{grid-template-columns:1fr;padding-top:28px;gap:20px}.lede{font-size:16px}.events{display:flex}.port{aspect-ratio:1.3}.stats{gap:8px}.stat span{font-size:9px}.stat strong{font-size:24px}.ledger-line{grid-template-columns:64px 1fr 74px;gap:6px;font-size:12px}.ledger-line .running{display:none}.ledger-head h2{font-size:25px}h1{font-size:65px}}
