</style></head><body>
<header><nav class="nav"><a href="./">Chloe reads Jon</a><span>A small money experiment</span></nav><div class="hero"><div><p class="kicker">The forecast is in your hands</p><h1>Cashflow<br><em>Harbour.</em></h1></div><p class="lede">Payday lifts all boats. Rent has other plans.<br>Move through sixty days of bills and paydays to find the low tide hiding inside a perfectly ordinary month.</p></div></header>
<main><div class="layout"><section aria-label="Cashflow forecast">
<div class="port"><img src="?art=1" alt="Original painted miniature harbour with a coral tugboat, lighthouse, and mustard-coloured waterfront buildings"><div class="water" id="water"></div><span class="port-caption">THE BALANCE BASIN · ILLUSTRATIVE WATERLINE</span><div class="tide-label"><span id="dateLabel"></span><strong id="balanceLabel"></strong></div></div>
<div class="scrub"><label for="day"><strong>Walk along the waterfront</strong><span id="dayLabel">Day 1 / 60</span></label><input id="day" type="range" min="0" max="59" value="0"><div id="dayEvents" class="small" aria-live="polite"></div></div>
<div class="stats" aria-live="polite"><div class="stat"><span>Lowest tide</span><strong id="minimum"></strong><small id="minDate"></small></div><div class="stat"><span>At day sixty</span><strong id="ending"></strong><small>End-of-day balance</small></div><div class="stat"><span>Extra cushion</span><strong id="cushion"></strong><small>To keep every day ≥ $0</small></div></div>
<div class="chart-title"><h2>The sixty-day shoreline</h2><span class="zero-key">Dashed line = $0</span></div>
<div class="chart-wrap"><svg id="chart" viewBox="0 0 640 205" role="img" aria-label="Balance forecast over sixty days"></svg><div class="legend"><span id="chartStart"></span><span id="chartEnd"></span></div></div>
<p class="tip">The picture's waterline follows the balance, not a physical scale. The chart includes your opening balance and all sixty daily closing balances.</p>
<div class="note" id="insight" aria-live="polite"></div>
</section>
<section class="panel" aria-label="Forecast settings"><p class="kicker">Harbourmaster's desk</p><h2>Set the tides.</h2>
<div class="controls"><label class="field">Opening balance ($)<input id="opening" type="number" value="650" min="-1000000" max="1000000" step="25"></label><label class="field">First forecast day<input id="start" type="date"></label></div>
<div class="preset" aria-label="Example forecasts"><button id="everyday">Everyday harbour</button><button id="tight">The tight Tuesday</button></div>
<p class="small">Positive amounts come in. Negative amounts go out. Each date is the first occurrence; repeat from there.</p>
<div id="events" class="events"></div><div class="actions"><button id="add" class="primary">+ Add a tide</button><button id="export">Export ledger CSV</button></div><p id="message" class="toast" role="status"></p>
<p class="small">Try moving rent two days later. Does the lowest balance change even when the total stays the same?</p>
<div class="note"><strong>Paper boats, fictional dollars.</strong><br>This is a scratchpad, not a bank connection. Nothing is sent or saved. Same-day entries are netted into one daily balance; intraday ordering, fees, and interest are not modelled.</div>
</section></div>
<section class="ledger"><div class="ledger-head"><h2>The shipping ledger</h2><span class="small" id="ledgerCount"></span></div><div class="ledger-list" id="ledger"></div></section>
</main><footer>Inspired by Jon's <a href="?source=1">cashflow.rb</a>, his 2006 Ruby script for seeing a bank balance rise and fall.<br>A tiny harbour by Chloe · Original generated harbour illustration · All figures are examples in dollars.</footer>
<script>
'use strict';
const $=id=>document.getElementById(id), DAY=86400000, money=n=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:n%100===0?0:2}).format(n/100);
const iso=d=>d.toISOString().slice(0,10), date=s=>new Date(s+'T12:00:00Z'), pretty=s=>date(s).toLocaleDateString('en-CA',{month:'short',day:'numeric',timeZone:'UTC'});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let events=[], forecast=[], ledger=[], opening=65000;
const today=new Date();$('start').value=today.getFullYear()+'-'+String(today.getMonth()+1).padStart(2,'0')+'-'+String(today.getDate()).padStart(2,'0');
function at(n){return iso(new Date(date($('start').value).getTime()+n*DAY))}
function preset(tight=false){
 $('opening').value=tight?300:650;
 events=tight?[{name:'Payday',amount:1250,repeat:'14',first:at(3)},{name:'Rent',amount:-900,repeat:'month',first:at(1)},{name:'Groceries',amount:-105,repeat:'7',first:at(0)},{name:'Phone',amount:-45,repeat:'month',first:at(6)}]:[{name:'Payday',amount:1250,repeat:'14',first:at(4)},{name:'Rent',amount:-900,repeat:'month',first:at(1)},{name:'Groceries',amount:-105,repeat:'7',first:at(2)},{name:'Phone',amount:-45,repeat:'month',first:at(8)}];
 $('day').value=0;renderEvents();compute();
}
function renderEvents(){
 $('events').innerHTML=events.map((e,i)=>'<div class="event"><div class="rowtop"><label class="field">Name<input data-i="'+i+'" data-key="name" maxlength="60" value="'+esc(e.name)+'"></label><label class="field">Amount ($)<input data-i="'+i+'" data-key="amount" type="number" min="-1000000" max="1000000" step="0.01" value="'+e.amount+'"></label><button class="delete" data-remove="'+i+'" aria-label="Remove '+esc(e.name)+'">×</button></div><div class="rowbottom"><label class="field">Repeats<select data-i="'+i+'" data-key="repeat">'+[['once','Just once'],['7','Every 7 days'],['14','Every 14 days'],['month','Monthly']].map(([v,t])=>'<option value="'+v+'"'+(e.repeat===v?' selected':'')+'>'+t+'</option>').join('')+'</select></label><label class="field">First date<input data-i="'+i+'" data-key="first" type="date" value="'+e.first+'"></label></div></div>').join('');
}
function occurs(e,s){
 if(!e.first||!Number.isFinite(date(e.first).getTime())||s<e.first)return false;
 if(e.repeat==='once')return s===e.first;
 if(e.repeat==='month'){
  const d=date(s), f=date(e.first),last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();
  return d.getUTCDate()===Math.min(f.getUTCDate(),last);
 }
 return Math.round((date(s)-date(e.first))/DAY)%Number(e.repeat)===0;
}
function compute(){
 if(!$('start').value||!Number.isFinite(date($('start').value).getTime())){$('message').textContent='Choose a first forecast day.';return}
 opening=Math.round(Number($('opening').value||0)*100);
 let balance=opening;forecast=[];ledger=[];
 for(let n=0;n<60;n++){
  const s=at(n), hits=events.filter(e=>occurs(e,s)).map(e=>({...e,cents:Math.round(Number(e.amount||0)*100)}));
  balance+=hits.reduce((a,e)=>a+e.cents,0);
  forecast.push({date:s,balance,hits});
  hits.forEach(e=>ledger.push({date:s,name:e.name,amount:e.cents,balance}));
 }
 const low=forecast.reduce((a,b)=>b.balance<a.balance?b:a),min=Math.min(opening,low.balance),end=forecast[59].balance;
 $('minimum').textContent=money(min);$('minimum').className=min<0?'danger':'';$('minDate').textContent=opening<low.balance?'Opening balance':pretty(low.date);
 $('ending').textContent=money(end);$('ending').className=end<0?'danger':'';
 $('cushion').textContent=money(Math.max(0,-min));
 const underwater=forecast.filter(d=>d.balance<0).length,delta=end-opening;
 $('insight').innerHTML='<strong>'+(underwater?underwater+' days below the breakwater.':'All sixty days stay afloat.')+'</strong><br>'+(underwater?'An extra '+money(-min)+' at the start would keep the daily closing balance from going negative. ':'Your lowest daily closing balance is '+money(low.balance)+'. ')+(delta>=0?'The period adds ':'The period uses ')+money(Math.abs(delta))+'. Timing and totals tell different stories.';
 $('chartStart').textContent=pretty(forecast[0].date);$('chartEnd').textContent=pretty(forecast[59].date);
 $('ledgerCount').textContent=ledger.length+' scheduled entries';
 $('ledger').innerHTML=ledger.length?ledger.map(e=>'<div class="ledger-line"><span>'+pretty(e.date)+'</span><span>'+esc(e.name)+'</span><span class="'+(e.amount<0?'danger':'')+'">'+money(e.amount)+'</span><span class="running">'+money(e.balance)+'</span></div>').join(''):'<p class="small">A quiet harbour. Add a tide to schedule money in or out.</p>';
 $('message').textContent='';draw();scrub();
}
function coordinates(){
 const vals=[opening,...forecast.map(d=>d.balance),0],lo=Math.min(...vals),hi=Math.max(...vals),pad=Math.max(10000,(hi-lo)*.12);
 return {x:i=>12+i*616/60,y:v=>185-(v-lo+pad)/(hi-lo+2*pad)*165,lo,hi};
}
function draw(){
 if(!forecast.length)return;
 const {x,y}=coordinates(),vals=[opening,...forecast.map(d=>d.balance)],points=vals.map((v,i)=>x(i)+','+y(v)),zero=y(0);
 $('chart').innerHTML='<line x1="12" x2="628" y1="'+zero+'" y2="'+zero+'" stroke="#be442b" stroke-dasharray="5 5"/><polygon points="12,190 '+points.join(' ')+' 628,190" fill="#24697b" opacity=".10"/><polyline points="'+points.join(' ')+'" stroke="#24697b" stroke-width="3" fill="none" stroke-linejoin="round"/><line id="cursor" y1="12" y2="190" stroke="#153e49" opacity=".4"/><circle id="dot" r="5" fill="#be442b"/>';
}
function scrub(){
 if(!forecast.length)return;
 const n=Number($('day').value),d=forecast[n],{x,y,lo,hi}=coordinates();
 $('dateLabel').textContent=pretty(d.date)+' · closing balance';$('balanceLabel').textContent=money(d.balance);$('balanceLabel').className=d.balance<0?'danger':'';
 $('dayLabel').textContent='Day '+(n+1)+' / 60';
 $('water').style.height=(18+(d.balance-lo)/Math.max(1,hi-lo)*50)+'%';
 $('dayEvents').textContent=d.hits.length?d.hits.map(e=>(e.name||'Untitled')+' '+money(e.cents)).join(' · '):'No scheduled entries. A little quiet water.';
 $('cursor').setAttribute('x1',x(n+1));$('cursor').setAttribute('x2',x(n+1));$('dot').setAttribute('cx',x(n+1));$('dot').setAttribute('cy',y(d.balance));
}
$('day').addEventListener('input',scrub);$('opening').addEventListener('input',compute);$('start').addEventListener('change',compute);
$('events').addEventListener('input',e=>{const el=e.target;if(el.dataset.i===undefined)return;events[Number(el.dataset.i)][el.dataset.key]=el.dataset.key==='amount'?Number(el.value):el.value;compute()});
$('events').addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(!b)return;events.splice(Number(b.dataset.remove),1);renderEvents();compute();$('add').focus()});
$('everyday').onclick=()=>preset();$('tight').onclick=()=>preset(true);
$('add').onclick=()=>{if(events.length>=24){$('message').textContent='This harbour has room for 24 recurring entries.';return}events.push({name:'New tide',amount:-50,repeat:'once',first:at(0)});renderEvents();compute();const fields=$('events').querySelectorAll('[data-key="name"]');fields[fields.length-1].focus()};
$('export').onclick=()=>{
 const quote=v=>'"'+String(v).replace(/"/g,'""')+'"',safe=s=>/^[=+@\-\t\r]/.test(s)?"'"+s:s;
 const rows=[['Date','Entry','Change CAD','Daily closing balance CAD'],[$('start').value,'Opening balance','',(opening/100).toFixed(2)],...ledger.map(e=>[e.date,safe(e.name),(e.amount/100).toFixed(2),(e.balance/100).toFixed(2)])];
 const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='cashflow-harbour.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('message').textContent='Ledger exported. Daily closing balances include all entries on that date.';
};
preset();
</script></body></html>